/*
 * A008523  Numbers that do not contain the letter 't'.
 * https://oeis.org/A008523
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, word
 * Formula:   not stated
 * Range:     u8 n <= 16, u16 n <= 56, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   is_allowed_upto999
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computation: numbers whose English word representation contains no letter
   't'.  The sequence is generated by enumerating allowed numbers in ascending
   order, using the structure of the English number system.  */
#include <stdint.h>
#include <stdlib.h>
#include "../utils/is_allowed_upto999.h"

#define SMALL_ARRAY_SIZE 56
#define MILLIONS_ARRAY_SIZE 55
#define BELOW1E9_ARRAY_SIZE 3136

static idx_t small[SMALL_ARRAY_SIZE];
static idx_t millions[MILLIONS_ARRAY_SIZE];
static idx_t below1e9[BELOW1E9_ARRAY_SIZE];

/* Compare function for qsort on idx_t */
static int cmp_idx(const void *a, const void *b)
{
    idx_t va = *(const idx_t *)a;
    idx_t vb = *(const idx_t *)b;
    return (va < vb) ? -1 : (va > vb);
}

/* One‑time initialization of the static tables.  */
static void init_tables(void)
{
    static int done = 0;
    if (done) return;
    done = 1;

    /* Build small[] (allowed numbers <1000) */
    idx_t sz = 0;
    for (idx_t i = 0; i < 1000; ++i)
        if (is_allowed_upto999(i)) small[sz++] = i;
    /* sz should be SMALL_ARRAY_SIZE */

    /* Build millions[] (allowed non‑zero numbers <1000) */
    idx_t mz = 0;
    for (idx_t i = 0; i < sz; ++i)
        if (small[i] != 0) millions[mz++] = small[i];
    /* mz should be MILLIONS_ARRAY_SIZE */

    /* Build below1e9[]: all allowed numbers <1,000,000,000
       (thousands group must be zero) */
    idx_t bz = 0;
    for (idx_t i = 0; i < sz; ++i)
        below1e9[bz++] = small[i];                     /* <1000 */
    for (idx_t j = 0; j < mz; ++j)                     /* millions groups */
    {
        idx_t base = millions[j] * 1000000ULL;
        for (idx_t i = 0; i < sz; ++i)
            below1e9[bz++] = base + small[i];
    }
    qsort(below1e9, bz, sizeof(idx_t), cmp_idx);
    /* bz should be BELOW1E9_ARRAY_SIZE */
}

seq_t a(idx_t n)
{
    init_tables();

    /* 1. Numbers < 1000 */
    if (n <= SMALL_ARRAY_SIZE)
        return (seq_t)small[n - 1];

    n -= SMALL_ARRAY_SIZE;

    /* 2. Blocks of size 1,000,000 (million level) */
    const idx_t block_small = SMALL_ARRAY_SIZE;            // 56
    const idx_t millions_total = MILLIONS_ARRAY_SIZE * block_small; // 55*56 = 3080
    if (n <= millions_total)
    {
        idx_t block_idx = (n - 1) / block_small;
        idx_t rem_idx  = (n - 1) % block_small;
        idx_t m = millions[block_idx];
        idx_t r = small[rem_idx];
        return (seq_t)(m * 1000000ULL + r);
    }

    n -= millions_total;

    /* 3. Blocks of size 1,000,000,000 (billion level) */
    const idx_t block_below1e9 = BELOW1E9_ARRAY_SIZE;      // 3136
    const idx_t billions_total = MILLIONS_ARRAY_SIZE * block_below1e9; // 55*3136 = 172480
    if (n <= billions_total)
    {
        idx_t block_idx = (n - 1) / block_below1e9;
        idx_t rem_idx  = (n - 1) % block_below1e9;
        idx_t b = millions[block_idx];
        idx_t r = below1e9[rem_idx];
        return (seq_t)(b * 1000000000ULL + r);
    }

    /* If n is larger than the range covered above, the sequence requires
       consideration of higher scale words such as 'quadrillion'.
       Those scales appear only far beyond the test limits (n ~ 10^4),
       so this branch is never reached in practice.  */
    return (seq_t)0;
}
